  "state": {},
  "elements": {
    "root_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "lg",
        "padding": 16
      },
      "children": [
        "main_title",
        "intro_text",
        "weekly_breakdown_title",
