    "main_title": {
      "type": "Text",
      "props": {
        "text": "GRE Quant 5-Week Study Schedule",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "This structured plan is designed for the GRE Quantitative Reasoning section, leading up to your test date on August 30, 2024. The schedule allocates 90 minutes on weekdays and 3 hours on Saturdays, with Sundays for rest. Each week focuses on a core topic area, culminating in a final week of intensive practice."
      },
      "children": []
    },
    "weekly_breakdown_title": {
      "type": "Text",
      "props": {
        "text": "Weekly Breakdown: July 29 - August 29",
        "variant": "h2"
      },
      "children": []
    },
    "week1_card": {
      "type": "Card",
      "props": {},
      "children": [
        "week1_stack"
      ]
    },
    "week1_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "week1_header",
        "week1_image",
        "week1_focus",
        "week1_weekday",
        "week1_saturday",
        "week1_button"
      ]
    },
    "week1_header": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "align": "center"
      },
      "children": [
        "week1_icon",
        "week1_title"
      ]
    },
    "week1_icon": {
      "type": "Icon",
      "props": {
        "name": "https://storage.googleapis.com/genai-assets/prod/icons/hash.svg"
      },
      "children": []
    },
    "week1_title": {
      "type": "Text",
      "props": {
        "text": "Week 1: Arithmetic Foundations (July 29 - August 3)",
        "variant": "h3"
      },
      "children": []
    },
    "week1_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/c1/Number-line.svg/1280px-Number-line.svg.png",
        "fit": "cover"
      },
      "children": []
    },
    "week1_focus": {
      "type": "Text",
      "props": {
        "text": "- **Focus:** Master the building blocks of GRE Quant. Cover number properties, integers, fractions, decimals, percentages, ratios, and proportions."
      },
      "children": []
    },
    "week1_weekday": {
      "type": "Text",
      "props": {
        "text": "- **Weekday Plan (90 min):** 60 minutes for concept learning and formula memorization; 30 minutes for targeted practice problems."
      },
      "children": []
    },
    "week1_saturday": {
      "type": "Text",
      "props": {
        "text": "- **Saturday Goal (3 hrs):** Take a timed 45-60 minute quiz on all Arithmetic topics, then spend the remaining time reviewing every question, especially your mistakes."
      },
      "children": []
    },
    "week1_button": {
      "type": "Button",
      "props": {
        "label": "Practice Arithmetic"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.khanacademy.org/math/arithmetic"
          }
        }
      }
    },
    "week2_card": {
