    "week2_icon": {
      "type": "Icon",
      "props": {
        "name": "https://storage.googleapis.com/genai-assets/prod/icons/x-lg.svg"
      },
      "children": []
    },
    "week2_title": {
      "type": "Text",
      "props": {
        "text": "Week 2: Algebra & Coordinate Geometry (August 5 - August 10)",
        "variant": "h3"
      },
      "children": []
    },
    "week2_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/13/Quadratic_formula.svg/1200px-Quadratic_formula.svg.png",
        "fit": "cover"
      },
      "children": []
    },
    "week2_focus": {
      "type": "Text",
      "props": {
        "text": "- **Focus:** Algebraic manipulations, equations, inequalities, exponents, roots, functions, and word problems. Introduce coordinate geometry concepts like lines, slopes, and quadrants."
      },
      "children": []
    },
    "week2_weekday": {
      "type": "Text",
      "props": {
        "text": "- **Weekday Plan (90 min):** 60 minutes on algebraic concepts and strategies; 30 minutes applying them to GRE-style questions."
      },
      "children": []
    },
    "week2_saturday": {
      "type": "Text",
      "props": {
        "text": "- **Saturday Goal (3 hrs):** Complete a timed quiz covering Algebra and basic Coordinate Geometry. Analyze your problem-solving process and speed for each question."
      },
      "children": []
    },
    "week2_button": {
      "type": "Button",
      "props": {
        "label": "Practice Algebra"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.khanacademy.org/math/algebra"
          }
        }
      }
    },
