    "week3_title": {
      "type": "Text",
      "props": {
        "text": "Week 3: Geometry (August 12 - August 17)",
        "variant": "h3"
      },
      "children": []
    },
    "week3_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e8/Pythagorean_theorem_demonstration.svg/1200px-Pythagorean_theorem_demonstration.svg.png",
        "fit": "cover"
      },
      "children": []
    },
    "week3_focus": {
      "type": "Text",
      "props": {
        "text": "- **Focus:** Deep dive into shapes and their properties. Cover lines, angles, triangles, quadrilaterals, circles, polygons, and 3D solids (cubes, cylinders)."
      },
      "children": []
    },
    "week3_weekday": {
      "type": "Text",
      "props": {
        "text": "- **Weekday Plan (90 min):** 60 minutes memorizing geometry rules and theorems; 30 minutes on practice problems, focusing on visual and spatial reasoning."
      },
      "children": []
    },
    "week3_saturday": {
      "type": "Text",
      "props": {
        "text": "- **Saturday Goal (3 hrs):** Take a timed quiz focused solely on Geometry. Use the review time to create flashcards for any formulas you forgot."
      },
      "children": []
    },
    "week3_button": {
      "type": "Button",
      "props": {
        "label": "Practice Geometry"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.khanacademy.org/math/geometry"
          }
        }
      }
    },
