      "type": "Text",
      "props": {
        "text": "Week 4: Data Analysis & Mixed Review (August 19 - August 24)",
        "variant": "h3"
      },
      "children": []
    },
    "week4_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/88/Misleading_y-axis_in_a_line_graph.png/1024px-Misleading_y-axis_in_a_line_graph.png",
        "fit": "cover"
      },
      "children": []
    },
    "week4_focus": {
      "type": "Text",
      "props": {
        "text": "- **Focus:** Data interpretation from graphs, charts, and tables. Cover statistics (mean, median, mode, standard deviation), probability, and combinatorics (permutations, combinations)."
      },
      "children": []
    },
    "week4_weekday": {
      "type": "Text",
      "props": {
        "text": "- **Weekday Plan (90 min):** 60 minutes on data and probability concepts; 30 minutes on mixed problem sets that include topics from previous weeks."
      },
      "children": []
    },
    "week4_saturday": {
      "type": "Text",
      "props": {
        "text": "- **Saturday Goal (3 hrs):** Complete a timed quiz with a heavy emphasis on Data Analysis but also including questions from all four topic areas to simulate test variety."
      },
      "children": []
    },
    "week4_button": {
      "type": "Button",
      "props": {
        "label": "Practice Data Analysis"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.khanacademy.org/math/statistics-probability"
          }
        }
      }
    },
