      "type": "Text",
      "props": {
        "text": "Week 5: Final Review & Practice Tests (August 26 - August 29)",
        "variant": "h3"
      },
      "children": []
    },
    "week5_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e4/Computer-based_testing.jpg/1280px-Computer-based_testing.jpg",
        "fit": "cover"
      },
      "children": []
    },
    "week5_focus": {
      "type": "Text",
      "props": {
        "text": "- **Focus:** Building stamina and refining test-day strategy. This week is dedicated to full-length, timed practice exams."
      },
      "children": []
    },
    "week5_plan": {
      "type": "Text",
      "props": {
        "text": "- **Plan:** Take a full-length PowerPrep test on Monday and Wednesday. Use the 90 minutes on Tuesday and Thursday for in-depth review of the previous day's test, focusing on pacing, errors, and strategy."
      },
      "children": []
    },
    "week5_final_day": {
      "type": "Text",
      "props": {
        "text": "- **Final Day (Aug 29):** Light review of key formulas and concepts. Do not take a full test. Rest well and ensure you are prepared for test day."
      },
      "children": []
    },
    "week5_button": {
      "type": "Button",
      "props": {
        "label": "Access PowerPrep Tests"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.ets.org/gre/prepare-for-the-test/test-prep-materials/powerprep-online"
          }
        }
      }
    },
    "quick_actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "wrap": "wrap"
      },
      "children": [
